    {
      "name": "MvPolynomial.eval₂_sum",
      "type": " {R : Type u} {S₁ : Type v} {S₂ : Type w} {σ : Type u_1} [CommSemiring R] [CommSemiring S₁] (f : R →+* S₁) (g : σ → S₁) (s : Finset S₂) (p : S₂ → MvPolynomial σ R) : MvPolynomial.eval₂ f g (∑ x ∈ s, p x) = ∑ x ∈ s, MvPolynomial.eval₂ f g (p x)",
      "module": "Mathlib.Algebra.MvPolynomial.Eval"
    },
    {
      "name": "MvPolynomial.eval₂_eq'",
      "type": " {R : Type u} {S₁ : Type v} {σ : Type u_1} [CommSemiring R] [CommSemiring S₁] [Fintype σ] (g : R →+* S₁) (X : σ → S₁) (f : MvPolynomial σ R) : MvPolynomial.eval₂ g X f = ∑ d ∈ f.support, g (f.coeff d) * ∏ i, X i ^ d i",
      "module": "Mathlib.Algebra.MvPolynomial.Eval"
    },
    {
      "name": "MvPolynomial.eval₂_eq",
      "type": " {R : Type u} {S₁ : Type v} {σ : Type u_1} [CommSemiring R] [CommSemiring S₁] (g : R →+* S₁) (X : σ → S₁) (f : MvPolynomial σ R) : MvPolynomial.eval₂ g X f = ∑ d ∈ f.support, g (f.coeff d) * ∏ i ∈ d.support, X i ^ d i",
      "module": "Mathlib.Algebra.MvPolynomial.Eval"
    }
  ]
}
